internal fun nativeParameterSearchIndex(context:Context):List<ParameterSearchTarget> = nativeParameters.mapNotNull { item ->
    val tool=PhotoTool.entries.mapNotNull { tool ->
        tool.nativePaths().filter { item.path==it || item.path.startsWith("$it.") }.maxByOrNull { it.length }?.let { tool to it.length }
    }.maxByOrNull { it.second }?.first ?: return@mapNotNull null
    val group=if(tool==PhotoTool.SCAN)"scan-detail" else "native-${context.getString(item.section)}"
    ParameterSearchTarget(tool,item.path,context.getString(item.label),group,native=true)
}

/** Saved targets use parameter identity when the user changes the application language. */
internal fun ParameterSearchTarget.resolvedGroupId(context:Context):String? {
    if(!native)return groupId
    if(tool==PhotoTool.SCAN)return "scan-detail"
    val parameter=nativeParameters.firstOrNull{it.path==path}?:return groupId
    return "native-${context.getString(parameter.section)}"
}
